import{_ as a,c as o,o as t,a3 as l}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Time off allocations","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/allocations/index.md","filePath":"master/human-resources/time-off/allocations/index.md","lastUpdated":1791902625000}'),s={name:"master/human-resources/time-off/allocations/index.md"};function n(i,e,r,c,h,d){return t(),o("div",null,e[0]||(e[0]=[l('<h1 id="time-off-allocations" tabindex="-1">Time off allocations <a class="header-anchor" href="#time-off-allocations" aria-label="Permalink to &quot;Time off allocations&quot;">​</a></h1><p>An allocation is a balance of days that you grant to an employee for one leave type. An allocation is the stock of days that requests spend. Without an approved allocation for a type, the employee cannot request that leave.</p><blockquote><p><strong>In simple words:</strong> An allocation says &quot;this person may take this many days of this leave type&quot;. Requests spend the days.</p></blockquote><p>Open <code>Time Off → My Time → My Allocation</code> to see your own allocations. Open <code>Time Off → Management → Allocation</code> to manage everyone&#39;s.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>Check the leave type in <a href="./../setup/time-off-types.html">Time off types</a>. Set up the allocation before the first request of that type.</p></div><h2 id="how-the-balance-works" tabindex="-1">How the balance works <a class="header-anchor" href="#how-the-balance-works" aria-label="Permalink to &quot;How the balance works&quot;">​</a></h2><p>The balance is the days allocated, minus the days already used by requests. Only <strong>Approved</strong> allocations count. Requests that are not <strong>Refused</strong> use days. This includes requests that still wait for approval.</p><p>Example from this guide: Sarah Mitchell has <strong>Paid Time Off 2026</strong>, an allocation of <strong>20</strong> days. She requests 3 days and a manager approves them.</p><ul><li>Allocated: 20 days.</li><li>Taken: 3 days.</li><li>Balance: 17 days.</li></ul><p>The balance shows on the cards in <a href="./../requests/my-time.html">My Time</a>. Each card shows the days left and a line such as <strong>Valid until 2026-12-31</strong>.</p><h2 id="when-a-request-is-denied" tabindex="-1">When a request is denied <a class="header-anchor" href="#when-a-request-is-denied" aria-label="Permalink to &quot;When a request is denied&quot;">​</a></h2><p>Without an approved allocation, Aureus denies the request. A <strong>Leave Request Denied</strong> message appears, for example <code>You do not have any allocated leave for Paid Time Off.</code> The same happens for <strong>Sick Time Off</strong>: <code>You do not have any allocated leave for Sick Time Off.</code> Nothing is saved.</p><p>In this guide Priya Sharma gets a 12 day <strong>Paid Time Off</strong> allocation and a 5 day <strong>Sick Time Off</strong> allocation.</p><h2 id="the-two-ways-to-create-an-allocation" tabindex="-1">The two ways to create an allocation <a class="header-anchor" href="#the-two-ways-to-create-an-allocation" aria-label="Permalink to &quot;The two ways to create an allocation&quot;">​</a></h2><ul><li>An employee asks for days from <code>Time Off → My Time → My Allocation</code>. See <a href="./my-allocation.html">My allocation</a>.</li><li>A manager creates the allocation for an employee in <code>Time Off → Management → Allocation</code>. See <a href="./manage-allocations.html">Manage allocations</a>.</li></ul><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>An allocation moves through these statuses.</p><ol><li><strong>To Approve</strong>: the allocation exists but adds nothing to the balance yet.</li><li><strong>Approved</strong>: the days count in the balance.</li><li><strong>Refused</strong>: the allocation is rejected and adds nothing.</li></ol><p>A refused allocation can go back to <strong>To Approve</strong> with <strong>Mark as Ready to Confirm</strong>. See <a href="./manage-allocations.html">Manage allocations</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Give each employee a yearly allocation at the start of the year. Use a clear name, for example <strong>Paid Time Off 2026</strong>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./my-allocation.html">My allocation</a></li><li><a href="./manage-allocations.html">Manage allocations</a></li><li><a href="./../setup/time-off-types.html">Time off types</a></li><li><a href="./../requests/">Requests</a></li><li><a href="./../reporting/by-employees.html">By Employees report</a></li></ul>',22)]))}const p=a(s,[["render",n]]);export{m as __pageData,p as default};
